WITH ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY channel ORDER BY order_date ASC) AS row_num FROM orders) ranked WHERE row_num = 1) SELECT s.id, s.customer_id, s.status, s.amount, CASE WHEN status RLIKE '^(SHIPPED|PENDING)$' THEN 'OTHER_ZONE' WHEN status RLIKE '^(COMPLETED|CANCELLED)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS status_zone, (SELECT MIN(o2.discount) FROM orders o2 WHERE o2.customer_id = s.customer_id) AS min_order_discount FROM ranked s ORDER BY status_zone DESC
